// Multi-channel normalizer (shared pattern across portfolio)
const raw = $input.first().json.body || $input.first().json;
let channel, normalized;

if (raw.entry?.[0]?.changes?.[0]?.value?.messages?.[0]) {
  channel = 'whatsapp';
  const msg = raw.entry[0].changes[0].value.messages[0];
  const contact = raw.entry[0].changes[0].value.contacts?.[0];
  normalized = {
    user_id: msg.from,
    user_name: contact?.profile?.name || null,
    message_text: msg.text?.body || '',
  };
} else if (raw.object === 'instagram' || raw.object === 'page') {
  channel = raw.object === 'instagram' ? 'instagram' : 'messenger';
  const event = raw.entry[0].messaging[0];
  normalized = {
    user_id: event.sender.id,
    user_name: null,
    message_text: event.message?.text || '',
  };
} else if (raw.message?.chat) {
  channel = 'telegram';
  normalized = {
    user_id: String(raw.message.from.id),
    user_name: `${raw.message.from.first_name || ''} ${raw.message.from.last_name || ''}`.trim(),
    message_text: raw.message.text || '',
  };
} else {
  throw new Error('Unknown channel');
}

return [{ json: { channel, ...normalized, received_at: new Date().toISOString() } }];

// Fuzzy service matching from user message
const userMsg = $('Normalize Message').first().json.message_text.toLowerCase();
const services = $('Get Services Catalog').all().map(s => s.json);

function scoreService(service) {
  const keywords = [
    service.service_name?.toLowerCase(),
    ...(service.alternate_names || '').toLowerCase().split(',').map(s => s.trim()),
    ...(service.keywords || '').toLowerCase().split(',').map(s => s.trim()),
  ].filter(Boolean);

  let score = 0;
  let matched = [];
  keywords.forEach(kw => {
    if (userMsg.includes(kw)) {
      score += kw.length;
      matched.push(kw);
    }
  });
  return { service, score, matchedKeywords: matched };
}

const matches = services
  .map(scoreService)
  .filter(m => m.score > 0)
  .sort((a, b) => b.score - a.score)
  .slice(0, 3);

const isAmbiguous = matches.length > 1 && matches[1].score >= matches[0].score * 0.7;

return [{
  json: {
    top_match: matches[0]?.service || null,
    alternative_matches: matches.slice(1).map(m => m.service),
    is_ambiguous: isAmbiguous,
    needs_clarification: !matches[0] || isAmbiguous,
  },
}];

